1	// The scan volume (react-three-fiber). One shader decides, per contact, whether the current sweep has acquired it.
2	// Each raw data type has its own colour (TYPE_COLOR); track state is the mark's shape: held contacts (known at the
3	// earlier checkpoint) are dots, contacts this sweep acquired are rings. The flare as the sweep passes, hover and the
4	// lock reticle turn white; blue is the sweep blade itself.
5	// The same rule drives the comments and the dated research on the time ring. Every ring element can be opened.
6	import { useEffect, useMemo, useRef } from "react";
7	import { useFrame, useThree, type ThreeEvent } from "@react-three/fiber";
8	import { Billboard, Html, OrbitControls } from "@react-three/drei";
9	import * as THREE from "three";
10	import type { PointsPayload, ResearchItem, Selection, SourcesPayload } from "@/lib/types";
11	import { CARS, CAR_NAME, LINES, LINE_CODES, MARKET_NAME, R, SWEEP_START, TAU, TIME_START, lineSector, polar, sector, timeAngle } from "./layout";
12	
13	const VERT = /* glsl */ `
14	attribute float aCp; attribute float aSel; attribute float aAz; attribute float aSize; attribute float aIdx;
15	uniform float uCp, uFrom, uSweep, uStart, uScale, uHover, uDim;
16	varying float vAlpha; varying float vRing; varying float vFlare; varying float vHov;
17	const float TAU = 6.2831853;
18	void main() {
19	  float lo = min(uCp, uFrom), hi = max(uCp, uFrom);
20	  float d = mod(aAz - uStart + 2.0 * TAU, TAU) / TAU;
21	  float passed = step(d, uSweep);
22	  float vis = aCp <= lo ? 1.0 : (aCp <= hi ? (uCp > uFrom ? passed : 1.0 - passed) : 0.0);
23	  vFlare = (uCp > uFrom && aCp > lo && aCp <= hi) ? passed * exp(-max(uSweep - d, 0.0) * 14.0) * (1.0 - pow(uSweep, 12.0)) : 0.0;
24	  vRing = abs(aCp - uCp) < 0.5 ? 1.0 : 0.0;          // acquired by the current sweep
25	  vHov = abs(aIdx - uHover) < 0.5 ? 1.0 : 0.0;
26	  vec4 mv = modelViewMatrix * vec4(position, 1.0);
27	  float depth = smoothstep(3.2, 7.5, -mv.z);           // far contacts recede
28	  vAlpha = vis * mix(uDim, 1.0, aSel) * mix(0.95, 0.4, depth);
29	  gl_Position = projectionMatrix * mv;
30	  gl_PointSize = aSize * uScale * (1.0 + vRing * 0.25 + vFlare * 2.0 + vHov * 2.2) / -mv.z;
31	}`;
32	const FRAG = /* glsl */ `
33	uniform vec3 uColor; uniform float uFade;
34	varying float vAlpha; varying float vRing; varying float vFlare; varying float vHov;
35	void main() {
36	  float r = length(gl_PointCoord - 0.5);
37	  if (r > 0.5) discard;
38	  float dot = smoothstep(0.5, 0.3, r);
39	  float ring = smoothstep(0.5, 0.42, r) * smoothstep(0.24, 0.32, r);
40	  float a = mix(dot, ring, vRing * (1.0 - vFlare));
41	  vec3 col = mix(uColor, vec3(1.0), max(vFlare, vHov));
42	  gl_FragColor = vec4(col, min(1.0, vAlpha + vHov) * a * uFade);
43	}`;
44	
45	// One colour per raw data type (validated categorical palette on black, dataviz reference dark steps).
46	export const TYPE_COLOR = { comment: "#3987e5", research: "#d95926", study: "#199e70", option: "#c98500", sales: "#d55181" } as const;
47	
48	function contactMaterial(scale: number, color: string) {
49	  return new THREE.ShaderMaterial({
50	    vertexShader: VERT, fragmentShader: FRAG, transparent: true, depthWrite: false,
51	    uniforms: {
52	      uCp: { value: 2 }, uFrom: { value: 2 }, uSweep: { value: 1 }, uStart: { value: SWEEP_START },
53	      uScale: { value: scale }, uHover: { value: -1 }, uDim: { value: 0.06 }, uFade: { value: 1 }, uColor: { value: new THREE.Color(color) },
54	    },
55	  });
56	}
57	
58	function attrGeometry(pos: Float32Array, attrs: Record<string, Float32Array>) {
59	  const g = new THREE.BufferGeometry();
60	  g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
61	  for (const [k, v] of Object.entries(attrs)) g.setAttribute(k, new THREE.BufferAttribute(v, 1));
62	  g.computeBoundingSphere();
63	  return g;
64	}
65	
66	/* ------------------------------------------------------------------------------------------- sweep clock */
67	function useSweep(mats: THREE.ShaderMaterial[], position: number, fromPosition: number, sweepId: number, onAngle: (a: number | null) => void) {
68	  const start = useRef<number | null>(null);
69	  const reduced = useMemo(() => window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false, []);
70	  useEffect(() => {
71	    for (const m of mats) { m.uniforms.uCp.value = position; m.uniforms.uFrom.value = fromPosition; m.uniforms.uSweep.value = reduced ? 1 : 0; }
72	    start.current = reduced || position === fromPosition ? null : performance.now();
73	  }, [sweepId]); // eslint-disable-line react-hooks/exhaustive-deps
74	  useFrame(() => {
75	    if (start.current == null) { onAngle(null); return; }
76	    const t = Math.min(1, (performance.now() - start.current) / 2400);
77	    const e = 1 - Math.pow(1 - t, 3);
78	    for (const m of mats) m.uniforms.uSweep.value = e;
79	    onAngle(t < 1 ? SWEEP_START + e * TAU : null);
80	    if (t >= 1) { start.current = null; for (const m of mats) m.uniforms.uFrom.value = m.uniforms.uCp.value; }
81	  });
82	}
83	
84	/* ------------------------------------------------------------------------------------------- camera fit */
85	function CameraFit() {
86	  const { camera, size } = useThree();
87	  useEffect(() => {
88	    const cam = camera as THREE.PerspectiveCamera;
89	    const aspect = size.width / size.height;
90	    cam.fov = aspect < 1 ? 58 : 40;
91	    const fit = (R.labels + 0.3) / (Math.tan(THREE.MathUtils.degToRad(cam.fov / 2)) * aspect);
92	    cam.position.setLength(Math.max(aspect < 1 ? 6 : 5.6, fit));
93	    cam.updateProjectionMatrix();
94	  }, [camera, size.width, size.height]);
95	  return null;
96	}
97	
98	/* ------------------------------------------------------------------------------------------- scene */
99	export interface Hover { title: string; sub?: string; comment?: number; acquiredHere?: boolean; x: number; y: number }
100	
101	interface SceneProps {
102	  points: PointsPayload;
103	  sources: SourcesPayload | undefined;
104	  mask: Uint8Array;
105	  position: number; fromPosition: number; sweepId: number;
106	  hoverComment: number | null;
107	  locked: [number, number, number] | null;
108	  onHover: (h: Hover | null) => void;
109	  onSelect: (s: Selection, at: [number, number, number]) => void;
110	}
111	
112	export const studyValue = (s: { scale: string; value: number | null }) =>
113	  s.value == null ? "" : s.scale === "dist_7" ? `${Math.round(s.value * 100)}% top-2` : `${s.value.toFixed(1)} / 10`;
114	
115	export function Scene(p: SceneProps) {
116	  const { gl } = useThree();
117	  const dpr = gl.getPixelRatio();
118	  const commentMat = useMemo(() => contactMaterial(15 * dpr, TYPE_COLOR.comment), [dpr]);
119	  const researchMat = useMemo(() => contactMaterial(19 * dpr, TYPE_COLOR.research), [dpr]);
120	  const sweepRef = useRef<THREE.Group>(null);
121	  const setCursor = (on: boolean) => { gl.domElement.style.cursor = on ? "pointer" : ""; };
122	
123	  /* comments */
124	  const comments = useMemo(() => {
125	    const c = p.points.cols, n = p.points.n;
126	    const pos = new Float32Array(n * 3), cp = new Float32Array(n), az = new Float32Array(n), size = new Float32Array(n), idx = new Float32Array(n);
127	    for (let i = 0; i < n; i++) {
128	      pos[i * 3] = c.x[i]; pos[i * 3 + 1] = c.y[i] * 0.72; pos[i * 3 + 2] = c.z[i];
129	      cp[i] = c.cp[i]; az[i] = Math.atan2(c.z[i], c.x[i]); idx[i] = i;
130	      size[i] = 0.85 + Math.min(0.8, Math.sqrt(c.len[i] / 300));
131	    }
132	    return attrGeometry(pos, { aCp: cp, aAz: az, aSize: size, aIdx: idx, aSel: new Float32Array(n).fill(1) });
133	  }, [p.points]);
134	  useEffect(() => {
135	    const a = comments.getAttribute("aSel") as THREE.BufferAttribute;
136	    for (let i = 0; i < p.mask.length; i++) a.setX(i, p.mask[i]);
137	    a.needsUpdate = true;
138	  }, [comments, p.mask]);
139	  useEffect(() => { commentMat.uniforms.uHover.value = p.hoverComment ?? -1; }, [commentMat, p.hoverComment]);
140	
141	  /* research on the time ring */
142	  const research = useMemo(() => {
143	    const items = (p.sources?.research ?? []).filter((r) => !r.ring);
144	    const n = items.length;
145	    const pos = new Float32Array(n * 3), cp = new Float32Array(n), az = new Float32Array(n), size = new Float32Array(n), idx = new Float32Array(n);
146	    items.forEach((it, i) => {
147	      const a = timeAngle(it.published_at);
148	      const lane = (it.id % 7) / 7;
149	      const [x, , z] = polar(R.time + (lane - 0.5) * 0.1, a);
150	      pos.set([x, (lane - 0.5) * 0.05, z], i * 3);
151	      cp[i] = it.new ? 2 : 1; az[i] = a; size[i] = it.tier === "T1" ? 1.5 : 1.1; idx[i] = i;
152	    });
153	    return { items, geom: attrGeometry(pos, { aCp: cp, aAz: az, aSize: size, aIdx: idx, aSel: new Float32Array(n).fill(1) }) };
154	  }, [p.sources]);
155	
156	  /* public research about one car line, on that car's study / options / sales ring (D-042) */
157	  const studyMat = useMemo(() => contactMaterial(17 * dpr, TYPE_COLOR.study), [dpr]);
158	  const optionMat = useMemo(() => contactMaterial(17 * dpr, TYPE_COLOR.option), [dpr]);
159	  const salesMat = useMemo(() => contactMaterial(17 * dpr, TYPE_COLOR.sales), [dpr]);
160	  const carRings = useMemo(() => {
161	    const all = (p.sources?.research ?? []).filter((r) => r.ring);
162	    const build = (ring: "study" | "options" | "sales", radius: number) => {
163	      // one entry per (item × car); the 5 Series' China items go to the long-wheelbase G68 part of the sector
164	      const slots = new Map<string, { it: ResearchItem; car: string }[]>();
165	      for (const it of all.filter((r) => r.ring === ring)) for (const car of it.cars) {
166	        const key = car === "G60" && it.region === "CN" ? "G68" : car;
167	        slots.set(key, [...(slots.get(key) ?? []), { it, car: key }]);
168	      }
169	      const items: ResearchItem[] = [], v: number[] = [], cp: number[] = [], az: number[] = [], size: number[] = [], idx: number[] = [], sticks: number[][] = [[], []];
170	      for (const [car, rows] of slots) {
171	        const [a0, a1] = sector(car);
172	        rows.sort((a, b) => (a.it.published_at ?? "").localeCompare(b.it.published_at ?? ""));
173	        rows.forEach(({ it }, i) => {
174	          const a = a0 + ((a1 - a0) * (i + 0.5)) / rows.length;
175	          const h = ring === "sales" && it.unit === "units" && it.value ? Math.min(0.42, (it.value / 120000) * 0.3) : 0;
176	          const [x, , z] = polar(radius + 0.07, a);
177	          v.push(x, h, z); cp.push(it.new ? 2 : 1); az.push(a); size.push(1.2); idx.push(items.length); items.push(it);
178	          if (h > 0) sticks[it.new ? 1 : 0].push(x, 0, z, x, h, z);
179	        });
180	      }
181	      const f = (a: number[]) => new Float32Array(a);
182	      return {
183	        items,
184	        geom: attrGeometry(f(v), { aCp: f(cp), aAz: f(az), aSize: f(size), aIdx: f(idx), aSel: new Float32Array(items.length).fill(1) }),
185	        sticks: sticks.map((s) => new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(s, 3))),
186	      };
187	    };
188	    return { study: build("study", R.study), options: build("options", R.options), sales: build("sales", R.sales) };
189	  }, [p.sources]);
190	
191	  useSweep([commentMat, researchMat, studyMat, optionMat, salesMat], p.position, p.fromPosition, p.sweepId, (a) => {
192	    const g = sweepRef.current;
193	    if (!g) return;
194	    g.visible = a != null;
195	    if (a != null) g.rotation.y = -a;
196	  });
197	
198	  /* picking */
199	  const first = (e: ThreeEvent<PointerEvent | MouseEvent>, ok: (i: number) => boolean) =>
200	    e.intersections.find((h) => h.object === e.object && h.index != null && ok(h.index))?.index ?? null;
201	  const commentOk = (i: number) => p.mask[i] === 1 && p.points.cols.cp[i] <= p.position;
202	  const researchOk = (i: number) => (research.items[i]?.new ? 2 : 1) <= p.position;
203	  const at = (g: THREE.BufferGeometry, i: number): [number, number, number] => {
204	    const a = g.getAttribute("position");
205	    return [a.getX(i), a.getY(i), a.getZ(i)];
206	  };
207	
208	  const onComment = {
209	    onPointerMove: (e: ThreeEvent<PointerEvent>) => {
210	      const i = first(e, commentOk);
211	      if (i == null) return;
212	      e.stopPropagation(); setCursor(true);
213	      p.onHover({ title: "", comment: i, acquiredHere: p.points.cols.cp[i] === p.position, x: e.nativeEvent.clientX, y: e.nativeEvent.clientY });
214	    },
215	    onPointerOut: () => { setCursor(false); p.onHover(null); },
216	    onClick: (e: ThreeEvent<MouseEvent>) => {
217	      const i = first(e, commentOk);
218	      if (i == null) return;
219	      e.stopPropagation(); p.onSelect({ kind: "comment", id: p.points.cols.id[i] }, at(comments, i));
220	    },
221	  };
222	  const onResearch = {
223	    onPointerMove: (e: ThreeEvent<PointerEvent>) => {
224	      const i = first(e, researchOk);
225	      if (i == null) return;
226	      e.stopPropagation(); setCursor(true);
227	      const it = research.items[i];
228	      p.onHover({ title: it.headline, sub: `Research · ${it.published_at ?? "undated"}`, x: e.nativeEvent.clientX, y: e.nativeEvent.clientY });
229	    },
230	    onPointerOut: () => { setCursor(false); p.onHover(null); },
231	    onClick: (e: ThreeEvent<MouseEvent>) => {
232	      const i = first(e, researchOk);
233	      if (i == null) return;
234	      e.stopPropagation(); p.onSelect({ kind: "research", item: research.items[i] }, at(research.geom, i));
235	    },
236	  };
237	
238	  const carRingHandlers = (layer: { items: ResearchItem[]; geom: THREE.BufferGeometry }, label: string) => {
239	    const ok = (i: number) => (layer.items[i]?.new ? 2 : 1) <= p.position;
240	    return {
241	      onPointerMove: (e: ThreeEvent<PointerEvent>) => {
242	        const i = first(e, ok);
243	        if (i == null) return;
244	        e.stopPropagation(); setCursor(true);
245	        const it = layer.items[i];
246	        p.onHover({ title: it.headline, sub: `${label} · ${it.published_at ?? "undated"}`, x: e.nativeEvent.clientX, y: e.nativeEvent.clientY });
247	      },
248	      onPointerOut: () => { setCursor(false); p.onHover(null); },
249	      onClick: (e: ThreeEvent<MouseEvent>) => {
250	        const i = first(e, ok);
251	        if (i == null) return;
252	        e.stopPropagation(); p.onSelect({ kind: "research", item: layer.items[i] }, at(layer.geom, i));
253	      },
254	    };
255	  };
256	
257	  return (
258	    <>
259	      <CameraFit />
260	      <OrbitControls makeDefault enablePan={false} minDistance={2.2} maxDistance={14}
261	                     enableDamping dampingFactor={0.08} maxPolarAngle={Math.PI * 0.62} />
262	      <points geometry={comments} material={commentMat} {...onComment} />
263	      <points geometry={research.geom} material={researchMat} {...onResearch} />
264	      <points geometry={carRings.study.geom} material={studyMat} {...carRingHandlers(carRings.study, "Public rating")} />
265	      <points geometry={carRings.options.geom} material={optionMat} {...carRingHandlers(carRings.options, "Product news")} />
266	      <points geometry={carRings.sales.geom} material={salesMat} {...carRingHandlers(carRings.sales, "Public sales")} />
267	      <lineSegments geometry={carRings.sales.sticks[0]}><lineBasicMaterial color={TYPE_COLOR.sales} transparent opacity={0.45} /></lineSegments>
268	      {p.position >= 2 && <lineSegments geometry={carRings.sales.sticks[1]}><lineBasicMaterial color={TYPE_COLOR.sales} transparent opacity={0.45} /></lineSegments>}
269	      <Rings sources={p.sources} onHover={p.onHover} onSelect={p.onSelect} setCursor={setCursor} />
270	      <group ref={sweepRef} visible={false}><SweepBlade /></group>
271	      {p.locked && <Reticle at={p.locked} />}
272	    </>
273	  );
274	}
275	
276	/* ------------------------------------------------------------------------------------------- sweep + lock */
277	function SweepBlade() {
278	  const mat = useMemo(() => new THREE.ShaderMaterial({
279	    transparent: true, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending,
280	    vertexShader: "varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }",
281	    fragmentShader: "varying vec2 vUv; void main(){ float a = (1.0 - vUv.x * 0.7) * (1.0 - abs(vUv.y - 0.5) * 2.0); gl_FragColor = vec4(0.18, 0.45, 0.95, 0.32 * a); }",
282	  }), []);
283	  return (
284	    <>
285	      <mesh material={mat} position={[(R.sales + 0.1) / 2, 0, 0]}><planeGeometry args={[R.sales + 0.1, 1.4]} /></mesh>
286	      <mesh position={[(R.sales + 0.1) / 2, 0, 0]}><boxGeometry args={[R.sales + 0.1, 0.004, 0.004]} /><meshBasicMaterial color="#4d94ff" /></mesh>
287	    </>
288	  );
289	}
290	
291	function Reticle({ at }: { at: [number, number, number] }) {
292	  const ref = useRef<THREE.Group>(null);
293	  useFrame(({ clock }) => { if (ref.current) ref.current.rotation.z = clock.elapsedTime * 0.8; });
294	  return (
295	    <Billboard position={at}>
296	      <group ref={ref}>
297	        {[0, 1, 2, 3].map((k) => (
298	          <mesh key={k} rotation={[0, 0, (k * Math.PI) / 2]}>
299	            <ringGeometry args={[0.045, 0.052, 16, 1, -0.45, 0.9]} />
300	            <meshBasicMaterial color="#ffffff" transparent opacity={0.95} depthTest={false} />
301	          </mesh>
302	        ))}
303	      </group>
304	    </Billboard>
305	  );
306	}
307	
308	/* ------------------------------------------------------------------------------------------- source rings */
309	function ringPoints(r: number, a0 = 0, a1 = TAU, seg = 256) {
310	  const pts: THREE.Vector3[] = [];
311	  for (let i = 0; i <= seg; i++) { const a = a0 + ((a1 - a0) * i) / seg; pts.push(new THREE.Vector3(...polar(r, a))); }
312	  return new THREE.BufferGeometry().setFromPoints(pts);
313	}
314	
315	const RING_BEARING = Math.PI / 2; // the gap between the 7 Series and 1 Series sectors faces the viewer
316	const RINGS: { r: number; name: string; color: string }[] = [
317	  { r: R.time, name: "Research", color: TYPE_COLOR.research }, { r: R.study, name: "Study", color: TYPE_COLOR.study },
318	  { r: R.options, name: "Options", color: TYPE_COLOR.option }, { r: R.sales, name: "Sales", color: TYPE_COLOR.sales },
319	];
320	
321	function Rings({ sources, onHover, onSelect, setCursor }: {
322	  sources: SourcesPayload | undefined;
323	  onHover: (h: Hover | null) => void;
324	  onSelect: (s: Selection, at: [number, number, number]) => void;
325	  setCursor: (on: boolean) => void;
326	}) {
327	  const lines = useMemo(() => {
328	    const guide = new THREE.LineBasicMaterial({ color: "#ffffff", transparent: true, opacity: 0.1 });
329	    const out: THREE.Line[] = [R.study, R.options, R.sales].flatMap((r) => CARS.map((car) => new THREE.Line(ringPoints(r, ...sector(car), 64), guide)));
330	    const time = new THREE.Line(ringPoints(R.time, TIME_START - 0.12, TIME_START + (300 / 360) * TAU, 360),
331	      new THREE.LineDashedMaterial({ color: "#ffffff", transparent: true, opacity: 0.22, dashSize: 0.02, gapSize: 0.025 }));
332	    time.computeLineDistances();
333	    out.push(time);
334	    return out;
335	  }, []);
336	
337	  // a bracket just outside the sales ring marking the China long-wheelbase part of the 5 Series sector
338	  const lwbArc = useMemo(() => new THREE.Line(ringPoints(R.sales + 0.08, ...sector("G68"), 32),
339	    new THREE.LineBasicMaterial({ color: "#ffffff", transparent: true, opacity: 0.35 })), []);
340	
341	  // study: a radial tick per item (outward = above this car × market's average item, inward = below); the tip is pickable
342	  const study = useMemo(() => {
343	    const list = sources?.study ?? [];
344	    const byCar = new Map<string, typeof list>();
345	    for (const s of list) byCar.set(s.car, [...(byCar.get(s.car) ?? []), s]);
346	    const seg: number[] = [], tips: number[] = [], items: typeof list = [];
347	    for (const [car, rows] of byCar) {
348	      const [a0, a1] = sector(car);
349	      rows.forEach((s, i) => {
350	        const a = a0 + ((a1 - a0) * (i + 0.5)) / rows.length;
351	        const tip = polar(R.study + Math.max(-2.5, Math.min(2.5, s.z ?? 0)) * 0.05, a);
352	        seg.push(...polar(R.study, a), ...tip);
353	        tips.push(...tip); items.push(s);
354	      });
355	    }
356	    return {
357	      items,
358	      lines: new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(seg, 3)),
359	      tips: new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(tips, 3)),
360	    };
361	  }, [sources]);
362	
363	  // options: one dot per equipment option of today's car
364	  const options = useMemo(() => {
365	    const list = sources?.options ?? [];
366	    const byCar = new Map<string, typeof list>();
367	    for (const o of list) byCar.set(o.car, [...(byCar.get(o.car) ?? []), o]);
368	    const v: number[] = [], items: typeof list = [];
369	    for (const [car, rows] of byCar) {
370	      const [a0, a1] = sector(car);
371	      rows.forEach((o, i) => { v.push(...polar(R.options + ((i % 3) - 1) * 0.018, a0 + ((a1 - a0) * (i + 0.5)) / rows.length)); items.push(o); });
372	    }
373	    return { items, geom: new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(v, 3)) };
374	  }, [sources]);
375	
376	  // sales: one bar per car × market × year; the 2030 forecast is an outline
377	  const bars = useMemo(() => {
378	    const rows = (sources?.sales ?? []).filter((s) => s.units && s.units > 0);
379	    const byCar = new Map<string, typeof rows>();
380	    for (const s of rows) byCar.set(s.car, [...(byCar.get(s.car) ?? []), s]);
381	    const out: { row: (typeof rows)[number]; pos: [number, number, number]; rot: number; h: number }[] = [];
382	    for (const [car, items] of byCar) {
383	      const [a0, a1] = sector(car);
384	      items.forEach((s, i) => {
385	        const a = a0 + ((a1 - a0) * (i + 0.5)) / items.length;
386	        const h = Math.max(0.01, (s.units! / 120000) * 0.3);
387	        out.push({ row: s, pos: polar(R.sales, a, h / 2), rot: -a, h });
388	      });
389	    }
390	    return out;
391	  }, [sources]);
392	
393	  const pick = (e: ThreeEvent<PointerEvent | MouseEvent>) =>
394	    e.intersections.find((h) => h.object === e.object && h.index != null)?.index ?? null;
395	  const pos = (g: THREE.BufferGeometry, i: number): [number, number, number] => {
396	    const a = g.getAttribute("position");
397	    return [a.getX(i), a.getY(i), a.getZ(i)];
398	  };
399	  const hover = (e: ThreeEvent<PointerEvent>, title: string, sub: string) => {
400	    e.stopPropagation(); setCursor(true); onHover({ title, sub, x: e.nativeEvent.clientX, y: e.nativeEvent.clientY });
401	  };
402	  const out = () => { setCursor(false); onHover(null); };
403	
404	  return (
405	    <group>
406	      {lines.map((l, i) => <primitive key={i} object={l} />)}
407	      <lineSegments geometry={study.lines}><lineBasicMaterial color={TYPE_COLOR.study} transparent opacity={0.75} /></lineSegments>
408	      <points geometry={study.tips}
409	              onPointerMove={(e) => { const i = pick(e); if (i != null) { const s = study.items[i]; hover(e, s.item, `Study · ${CAR_NAME[s.car]} · ${MARKET_NAME[s.market]} · ${studyValue(s)}`); } }}
410	              onPointerOut={out}
411	              onClick={(e) => { const i = pick(e); if (i != null) { e.stopPropagation(); onSelect({ kind: "study", item: study.items[i] }, pos(study.tips, i)); } }}>
412	        <pointsMaterial color={TYPE_COLOR.study} size={0.016} transparent opacity={0.9} />
413	      </points>
414	      <points geometry={options.geom}
415	              onPointerMove={(e) => { const i = pick(e); if (i != null) { const o = options.items[i]; hover(e, o.name ?? o.code ?? "Option", `Option · ${CAR_NAME[o.car]} · ${o.availability ?? ""}`); } }}
416	              onPointerOut={out}
417	              onClick={(e) => { const i = pick(e); if (i != null) { e.stopPropagation(); onSelect({ kind: "option", item: options.items[i] }, pos(options.geom, i)); } }}>
418	        <pointsMaterial color={TYPE_COLOR.option} size={0.014} transparent opacity={0.85} />
419	      </points>
420	      {bars.map((b, i) => (
421	        <mesh key={i} position={b.pos} rotation={[0, b.rot, 0]}
422	              onPointerMove={(e) => hover(e, `${(b.row.units ?? 0).toLocaleString("en-US")} cars`, `Sales · ${CAR_NAME[b.row.car]} · ${MARKET_NAME[b.row.market]} · ${b.row.year}${b.row.is_forecast ? " forecast" : ""}`)}
423	              onPointerOut={out}
424	              onClick={(e) => { e.stopPropagation(); onSelect({ kind: "sales", item: b.row }, [b.pos[0], b.h, b.pos[2]]); }}>
425	          <boxGeometry args={[0.014, b.h, 0.014]} />
426	          {b.row.is_forecast ? <meshBasicMaterial color={TYPE_COLOR.sales} wireframe transparent opacity={0.6} /> : <meshBasicMaterial color={TYPE_COLOR.sales} transparent opacity={0.85} />}
427	        </mesh>
428	      ))}
429	      {RINGS.map((g) => (
430	        <Html key={g.name} position={polar(g.r, RING_BEARING, 0.02)} center zIndexRange={[10, 0]}>
431	          <div className="ring-name"><i style={{ background: g.color }} />{g.name}</div>
432	        </Html>
433	      ))}
434	      {LINES.map((line) => {
435	        const [a0, a1] = lineSector(line);
436	        return (
437	          <Html key={line} position={polar(R.labels, (a0 + a1) / 2, 0.18)} center zIndexRange={[10, 0]}>
438	            <div className="ring-label"><b>{CAR_NAME[line]}</b><span>{LINE_CODES[line]}</span></div>
439	          </Html>
440	        );
441	      })}
442	      <primitive object={lwbArc} />
443	      <Html position={polar(R.sales + 0.17, (sector("G68")[0] + sector("G68")[1]) / 2, 0.02)} center zIndexRange={[10, 0]}>
444	        <div className="ring-sub">LWB · China</div>
445	      </Html>
446	      {[["JUL 25", "2025-07-01"], ["JAN 26", "2026-01-31"], ["JUL 26", "2026-07-31"]].map(([t, d]) => (
447	        <Html key={t} position={polar(R.time, timeAngle(d), 0.16)} center zIndexRange={[10, 0]}>
448	          <div className="time-label">{t}</div>
449	        </Html>
450	      ))}
451	    </group>
452	  );
453	}
