1	// Scan: every raw piece of evidence the system holds, at the current checkpoint, as one 3D space.
2	import { Suspense, useEffect, useMemo, useState } from "react";
3	import { Canvas } from "@react-three/fiber";
4	import { useQuery } from "@tanstack/react-query";
5	import { ExternalLink, X } from "lucide-react";
6	import { api } from "@/lib/api";
7	import type { Comment, PointsPayload, Selection, SourcesPayload } from "@/lib/types";
8	import { useCheckpoint } from "@/state/checkpoint";
9	import { Scene, TYPE_COLOR, studyValue, type Hover } from "./Scene";
10	import { CAR_NAME, MARKET_NAME } from "./layout";
11	import "./scan.css";
12	
13	const fmt = (n: number | undefined | null) => (n == null ? "–" : n.toLocaleString("en-US"));
14	
15	type Dim = "car" | "market" | "channel" | "type" | "engine";
16	const DIMS: { id: Dim; name: string }[] = [
17	  { id: "car", name: "Car" }, { id: "market", name: "Market" }, { id: "channel", name: "Channel" },
18	  { id: "type", name: "Label" }, { id: "engine", name: "Engine" },
19	];
20	function valueName(dim: Dim, v: string | null): string {
21	  if (v == null) return "Unlabelled";
22	  if (dim === "car") return CAR_NAME[v] ?? v;
23	  if (dim === "market") return MARKET_NAME[v] ?? v;
24	  return v;
25	}
