27	export function Scan() {
28	  const { from, sweepId, position, checkpoints } = useCheckpoint();
29	  const points = useQuery({ queryKey: ["scan", "points"], queryFn: () => api.get<PointsPayload>("/api/scan/points"), staleTime: Infinity });
30	  const sources = useQuery({ queryKey: ["scan", "sources"], queryFn: () => api.get<SourcesPayload>("/api/scan/sources?cp=cp2"), staleTime: Infinity });
31	  const [dim, setDim] = useState<Dim>("car");
32	  const [isolate, setIsolate] = useState<Set<number>>(new Set());
33	  const [hover, setHover] = useState<Hover | null>(null);
34	  const [selected, setSelected] = useState<{ sel: Selection; at: [number, number, number] } | null>(null);
35	  const fromPosition = checkpoints?.find((c) => c.id === from)?.position ?? position;
36	
37	  const mask = useMemo(() => {
38	    const n = points.data?.n ?? 0;
39	    const m = new Uint8Array(n).fill(1);
40	    if (!points.data || isolate.size === 0) return m;
41	    const col = points.data.cols[dim];
42	    for (let i = 0; i < n; i++) m[i] = isolate.has(col[i]) ? 1 : 0;
43	    return m;
44	  }, [points.data, dim, isolate]);
45	
46	  useEffect(() => {
47	    const onKey = (e: KeyboardEvent) => {
48	      if (e.key !== "Escape") return;
49	      if (selected) setSelected(null); else setIsolate(new Set());
50	    };
51	    window.addEventListener("keydown", onKey);
52	    return () => window.removeEventListener("keydown", onKey);
53	  }, [selected]);
54	
55	  return (
56	    <main className="scan" aria-label="Raw evidence at the selected checkpoint">
57	      <div className="scan-canvas">
58	        {points.data && (
59	          <Canvas dpr={[1, 2]} camera={{ position: [0, 2.3, 5.3], fov: 40, near: 0.05, far: 60 }}
60	                  raycaster={{ params: { Points: { threshold: 0.018 }, Line: { threshold: 0 }, Mesh: {}, LOD: {}, Sprite: {} } }}
61	                  gl={{ antialias: true, alpha: false }} onCreated={({ gl }) => gl.setClearColor("#000000")}
62	                  onPointerMissed={() => setSelected(null)}>
63	            <Suspense fallback={null}>
64	              <Scene points={points.data} sources={sources.data} mask={mask} position={position} fromPosition={fromPosition}
65	                     sweepId={sweepId} hoverComment={hover?.comment ?? null} locked={selected?.at ?? null}
66	                     onHover={setHover} onSelect={(sel, at) => { setSelected({ sel, at }); setHover(null); }} />
67	            </Suspense>
68	          </Canvas>
69	        )}
70	        {points.isPending && <div className="scan-state"><span className="scan-pulse" aria-hidden />Scanning</div>}
71	        {points.isError && <div className="scan-state error">{(points.error as Error).message}</div>}
72	      </div>
73	
74	      <Readout />
75	
76	      {points.data && (
77	        <Key points={points.data} position={position} dim={dim} isolate={isolate}
78	             onDim={(d) => { setDim(d); setIsolate(new Set()); }}
79	             onToggle={(v) => setIsolate((s) => { const n = new Set(s); n.has(v) ? n.delete(v) : n.add(v); return n; })}
80	             onClear={() => setIsolate(new Set())} />
81	      )}
82	
83	      {hover && !selected && <HoverCard hover={hover} points={points.data} />}
84	      {selected && <Inspector sel={selected.sel} sales={sources.data?.sales ?? []} onClose={() => setSelected(null)}
85	                              cpLabel={(id) => checkpoints?.find((c) => c.id === id)?.label ?? id} />}
86	    </main>
87	  );
88	}
