91	type GlyphKind = "comment" | "study" | "option" | "sales" | "research";
92	const GLYPH_COLOR: Record<GlyphKind, string> = {
93	  comment: TYPE_COLOR.comment, study: TYPE_COLOR.study, option: TYPE_COLOR.option, sales: TYPE_COLOR.sales, research: TYPE_COLOR.research,
94	};
95	function Glyph({ kind }: { kind: GlyphKind }) {
96	  const c = "currentColor";
97	  return (
98	    <svg width="14" height="14" viewBox="0 0 14 14" aria-hidden className="glyph" style={{ color: GLYPH_COLOR[kind] }}>
99	      {kind === "comment" && <><circle cx="4" cy="6" r="1.6" fill={c} /><circle cx="9.5" cy="4" r="1.6" fill="none" stroke={c} /><circle cx="8.5" cy="10" r="1.4" fill={c} /></>}
100	      {kind === "study" && <><path d="M2 8h10" stroke={c} strokeOpacity=".35" /><path d="M4 8V4M7 8v4M10 8V3" stroke={c} strokeWidth="1.3" /></>}
101	      {kind === "option" && <>{[2.5, 5.5, 8.5, 11.5].map((x) => <circle key={x} cx={x} cy="7" r="1" fill={c} />)}</>}
102	      {kind === "sales" && <><rect x="2.5" y="6" width="2" height="6" fill={c} /><rect x="6" y="3" width="2" height="9" fill={c} /><rect x="9.5" y="2.5" width="2" height="9.5" fill="none" stroke={c} /></>}
103	      {kind === "research" && <><path d="M1.5 9.5a6 6 0 0 1 11 0" fill="none" stroke={c} strokeDasharray="1.5 1.5" /><circle cx="7" cy="4.2" r="1.4" fill={c} /></>}
104	    </svg>
105	  );
106	}
