108	/* ------------------------------------------------------------------------------------------- readout */
109	function Readout() {
110	  const { current, position } = useCheckpoint();
111	  const s = current?.sources;
112	  const plus = (n: number | undefined) => (position > 1 && n ? <span className="plus">+{fmt(n)}</span> : null);
113	  const internal = s ? s.study.visible + s.option_list.visible + s.sales.visible : undefined;
114	  const cells: { k: GlyphKind; label: string; n: number | undefined; nu?: number }[] = [
115	    { k: "comment", label: "Comments", n: s?.feedback.visible, nu: s?.feedback.new },
116	    { k: "research", label: "Research", n: s?.research.visible, nu: s?.research.new },
117	    { k: "sales", label: "BMW data", n: internal },
118	  ];
119	  return (
120	    <dl className="readout" aria-label="Evidence at this checkpoint">
121	      {cells.map((c) => (
122	        <div key={c.label}>
123	          <dt>{c.k === "sales" ? <span className="glyph-trio"><Glyph kind="study" /><Glyph kind="option" /><Glyph kind="sales" /></span> : <Glyph kind={c.k} />}<span className="label">{c.label}</span></dt>
124	          <dd><span className="num">{fmt(c.n)}</span>{plus(c.nu)}</dd>
125	        </div>
126	      ))}
127	    </dl>
128	  );
129	}
