131	/* ------------------------------------------------------------------------------------------- key */
132	function Key(p: { points: PointsPayload; position: number; dim: Dim; isolate: Set<number>; onDim: (d: Dim) => void; onToggle: (v: number) => void; onClear: () => void }) {
133	  const values = p.points.dict[p.dim] as (string | null)[];
134	  const counts = useMemo(() => {
135	    const col = p.points.cols[p.dim], cps = p.points.cols.cp;
136	    const vis = new Array(values.length).fill(0);
137	    for (let i = 0; i < col.length; i++) if (col[i] >= 0 && cps[i] <= p.position) vis[col[i]]++;
138	    return vis as number[];
139	  }, [p.points, p.dim, p.position, values.length]);
140	  const max = Math.max(1, ...counts);
141	  return (
142	    <nav className="key" aria-label="Filter comments">
143	      <div className="key-dims" role="tablist">
144	        {DIMS.map((d) => <button key={d.id} role="tab" aria-selected={p.dim === d.id} onClick={() => p.onDim(d.id)}>{d.name}</button>)}
145	      </div>
146	      <ul className="key-values">
147	        {values.map((v, i) => {
148	          const n = counts[i];
149	          if (!n) return null;
150	          const on = p.isolate.size === 0 || p.isolate.has(i);
151	          return (
152	            <li key={i}>
153	              <button aria-pressed={p.isolate.has(i)} data-dim={on ? undefined : ""} onClick={() => p.onToggle(i)}>
154	                <span className="key-name">{valueName(p.dim, v)}</span>
155	                <span className="key-bar" aria-hidden><span style={{ transform: `scaleX(${n / max})` }} /></span>
156	                <span className="key-n">{fmt(n)}</span>
157	              </button>
158	            </li>
159	          );
160	        })}
161	      </ul>
162	      {p.isolate.size > 0 && <button className="key-clear" onClick={p.onClear}>Show all <span className="label">Esc</span></button>}
163	    </nav>
164	  );
165	}
