293	  const max = Math.max(1, ...series.map((s) => s.units ?? 0));
294	  return (
295	    <>
296	      <h2 className="sheet-title">{CAR_NAME[row.car] ?? row.car} · {MARKET_NAME[row.market] ?? row.market}</h2>
297	      <div className="minibars" role="img" aria-label="Sales by year">
298	        {series.map((s) => (
299	          <div key={s.year} className="minibar" data-on={s.year === row.year ? "" : undefined} data-forecast={s.is_forecast ? "" : undefined}>
300	            <span className="minibar-n">{fmt(s.units)}</span>
