17	const GAP = 0.08;            // radians between sectors
18	const LWB_SHARE = 0.28;      // share of the 5 Series sector given to the China long-wheelbase G68
19	
20	export function lineSector(line: string): [number, number] {
21	  const i = Math.max(0, LINES.indexOf(line as (typeof LINES)[number]));
22	  const a0 = START + (i * TAU) / LINES.length + GAP / 2;
23	  return [a0, a0 + TAU / LINES.length - GAP];
