28	  if (car === "G60" || car === "G68") {
29	    const [a0, a1] = lineSector("G60");
30	    const split = a1 - (a1 - a0) * LWB_SHARE;
31	    return car === "G60" ? [a0, split - GAP / 4] : [split + GAP / 4, a1];
