// Bottom-right sweep control: the two checkpoints as nodes on one track. The later node shows what its sweep did
// to the earlier one's tracks (held / new), so "JUL builds on JAN" is visible, not just stated.
import { useCheckpoint, CHECKPOINT_ORDER } from "@/state/checkpoint";
import type { Checkpoint, CheckpointId } from "@/lib/types";
import "./sweep.css";

const fmt = (n: number | undefined) => (n == null ? "–" : n.toLocaleString("en-US"));

export function SweepControl() {
  const { cp, setCp, checkpoints, sweepId } = useCheckpoint();
  const byId = Object.fromEntries((checkpoints ?? []).map((c) => [c.id, c]));
  // Same three groups as the readout (comments, research, BMW data), so held + new = the readout totals.
  const sum = (c: Checkpoint | undefined, f: "visible" | "new") =>
    c ? (["feedback", "research", "study", "option_list", "sales"] as const).reduce((n, k) => n + c.sources[k][f], 0) : undefined;
  const cur = byId[cp], parent = cur?.parent_id ? byId[cur.parent_id] : undefined;
  return (
    <div className="sweepctl" role="radiogroup" aria-label="Checkpoint">
      <div className="sweepctl-track" data-cp={cp}>
        <span className="sweepctl-line" />
        <span className="sweepctl-fill" key={sweepId} />
        {CHECKPOINT_ORDER.map((id: CheckpointId) => (
          <button
            key={id}
            role="radio"
            aria-checked={cp === id}
            className="sweepctl-node"
            data-on={cp === id || (cp === "cp2" && id === "cp1") ? "" : undefined}
            onClick={() => setCp(id)}
          >
            <span className="sweepctl-dot" aria-hidden />
            <span className="sweepctl-name">{byId[id]?.label ?? (id === "cp1" ? "JAN 26" : "JUL 26")}</span>
          </button>
        ))}
      </div>
      <div className="sweepctl-tracks" aria-live="polite">
        {parent ? (
          <>
            <span><i className="mark held" aria-hidden />{fmt(sum(parent, "visible"))}<span className="label">held</span></span>
            <span><i className="mark new" aria-hidden />{fmt(sum(cur, "new"))}<span className="label">new</span></span>
          </>
        ) : (
          <span><i className="mark new" aria-hidden />{fmt(sum(cur, "visible"))}<span className="label">acquired</span></span>
        )}
      </div>
    </div>
  );
}
.sweepctl {
  position: fixed; right: var(--edge); bottom: calc(var(--edge) + env(safe-area-inset-bottom, 0px)); z-index: 20;
  width: 280px; padding: 16px 18px 14px; border-radius: var(--r);
  background: var(--glass); border: 1px solid var(--hair);
  backdrop-filter: blur(14px) saturate(1.2); -webkit-backdrop-filter: blur(14px) saturate(1.2);
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.5), 0 24px 60px rgba(0, 0, 0, 0.6);
  display: grid; gap: 14px;
}
.sweepctl-track { position: relative; display: flex; justify-content: space-between; align-items: flex-start; }
.sweepctl-line, .sweepctl-fill { position: absolute; left: 6px; right: 6px; top: 6px; height: 1px; }
.sweepctl-line { background: var(--hair-2); }
