.sweepctl-node { position: relative; display: grid; gap: 8px; justify-items: start; padding: 0; border-radius: 6px; }
.sweepctl-node:last-child { justify-items: end; }
.sweepctl-dot {
  width: 13px; height: 13px; border-radius: 50%; background: var(--void); border: 1px solid var(--ink-3);
  transition: background var(--med) var(--ease), border-color var(--med) var(--ease), box-shadow var(--med) var(--ease);
}
