1	// Geometry of the scan volume. The comment galaxy sits in the unit ball. Just outside it runs the research time ring
2	// (angle = publication date, so the sweep that reveals the second checkpoint passes newer research in date order).
3	// Beyond that the car-specific rings (study, options, sales) run in one sector per car line, right under the car's
4	// name. The 5 Series sector holds the G60 and, in its last part, the China long-wheelbase G68 (D-042).
5	
6	export const TAU = Math.PI * 2;
7	
8	export const CARS = ["F70", "G60", "G68", "G70"] as const;           // derivatives in the data
9	export const LINES = ["F70", "G60", "G70"] as const;                 // one sector per car line
10	export const CAR_NAME: Record<string, string> = { F70: "1 Series", G60: "5 Series", G68: "5 Series LWB", G70: "7 Series" };
11	export const LINE_CODES: Record<string, string> = { F70: "F70", G60: "G60 · G68", G70: "G70" };
12	export const MARKET_NAME: Record<string, string> = { EU: "Europe", US: "USA", CN: "China", RoW: "Rest of world" };
13	
14	export const R = { time: 1.32, study: 1.6, options: 1.8, sales: 2.02, labels: 2.42 } as const;
15	
16	const START = Math.PI / 2;   // sectors start at the front, so the gap between the 7 and 1 Series faces the viewer
17	const GAP = 0.08;            // radians between sectors
18	const LWB_SHARE = 0.28;      // share of the 5 Series sector given to the China long-wheelbase G68
19	
20	export function lineSector(line: string): [number, number] {
21	  const i = Math.max(0, LINES.indexOf(line as (typeof LINES)[number]));
22	  const a0 = START + (i * TAU) / LINES.length + GAP / 2;
23	  return [a0, a0 + TAU / LINES.length - GAP];
24	}
25	
26	/** Angular span for one derivative's items on the car rings. */
27	export function sector(car: string): [number, number] {
28	  if (car === "G60" || car === "G68") {
29	    const [a0, a1] = lineSector("G60");
30	    const split = a1 - (a1 - a0) * LWB_SHARE;
31	    return car === "G60" ? [a0, split - GAP / 4] : [split + GAP / 4, a1];
32	  }
33	  return lineSector(car);
34	}
35	
36	// Time ring: Jul 2025 → Jul 2026 over 300°, the JAN cut-off at bearing 0 (viewer's right). Older items collect just
37	// before the start.
38	const T0 = Date.parse("2025-07-01");
39	const T1 = Date.parse("2026-07-31");
40	const SPAN = (300 / 360) * TAU;
41	export const TIME_START = -SPAN * ((Date.parse("2026-01-31") - T0) / (T1 - T0));
42	export function timeAngle(iso: string | null): number {
43	  const t = iso ? Date.parse(iso.length === 7 ? `${iso}-28` : iso.length === 4 ? `${iso}-12-31` : iso) : NaN;
44	  if (Number.isNaN(t) || t < T0) return TIME_START - 0.08;
45	  return TIME_START + SPAN * Math.min(1, (t - T0) / (T1 - T0));
46	}
47	export const SWEEP_START = timeAngle("2026-01-31"); // the sweep to JUL starts at the JAN cut-off
48	
49	export const polar = (r: number, a: number, y = 0): [number, number, number] => [r * Math.cos(a), y, r * Math.sin(a)];
50	
51	/** Study ticks: one per item, grouped by car in input order; tip offset outward/inward by the item's z-score. */
52	export function studyLayout<T extends { car: string; z: number | null }>(list: T[]) {
53	  const byCar = new Map<string, T[]>();
54	  for (const s of list) byCar.set(s.car, [...(byCar.get(s.car) ?? []), s]);
55	  const out: { item: T; base: [number, number, number]; tip: [number, number, number] }[] = [];
56	  for (const [car, rows] of byCar) {
57	    const [a0, a1] = sector(car);
58	    rows.forEach((s, i) => {
59	      const a = a0 + ((a1 - a0) * (i + 0.5)) / rows.length;
60	      out.push({ item: s, base: polar(R.study, a), tip: polar(R.study + Math.max(-2.5, Math.min(2.5, s.z ?? 0)) * 0.05, a) });
61	    });
62	  }
63	  return out;
64	}
65	
66	/** Option dots: one per equipment option, grouped by car in input order, in three slightly offset lanes. */
67	export function optionLayout<T extends { car: string }>(list: T[]) {
68	  const byCar = new Map<string, T[]>();
69	  for (const o of list) byCar.set(o.car, [...(byCar.get(o.car) ?? []), o]);
70	  const out: { item: T; at: [number, number, number] }[] = [];
71	  for (const [car, rows] of byCar) {
72	    const [a0, a1] = sector(car);
73	    rows.forEach((o, i) => out.push({ item: o, at: polar(R.options + ((i % 3) - 1) * 0.018, a0 + ((a1 - a0) * (i + 0.5)) / rows.length) }));
74	  }
75	  return out;
76	}
