// Filtering the scan. One dimension at a time, one or more values isolated. Car and market exist on every data type,
// so they filter the whole volume; the rest belong to one type and leave the others alone. Items with no value for a
// global dimension (options have no market, global research has none) stay visible: they apply everywhere.
import type { OptionItem, PointsPayload, ResearchItem, SalesRow, SourcesPayload, StudyItem } from "@/lib/types";
import { CARS, CAR_NAME, MARKET_NAME } from "./layout";

export type Dim = "car" | "market" | "channel" | "type" | "engine" | "tier" | "category";
export type Scope = "all" | "comment" | "research" | "option";
export const DIMS: { id: Dim; name: string; scope: Scope }[] = [
  { id: "car", name: "Car", scope: "all" }, { id: "market", name: "Market", scope: "all" },
  { id: "channel", name: "Channel", scope: "comment" }, { id: "type", name: "Label", scope: "comment" },
  { id: "engine", name: "Engine", scope: "comment" },
  { id: "tier", name: "Trust", scope: "research" }, { id: "category", name: "Category", scope: "option" },
];
export const SCOPE_NOTE: Record<Scope, string> = {
  all: "Filters all data", comment: "Customer comments only", research: "Web research only", option: "Equipment options only",
};
export const scopeOf = (d: Dim) => DIMS.find((x) => x.id === d)!.scope;

export interface Filter { dim: Dim; values: Set<string> }

const NONE = "∅";
const key = (v: string | null | undefined) => v ?? NONE;
const COMMENT_DIMS = ["car", "market", "channel", "type", "engine"] as const;
type CommentDim = (typeof COMMENT_DIMS)[number];
const isCommentDim = (d: Dim): d is CommentDim => (COMMENT_DIMS as readonly Dim[]).includes(d);

/** The 5 Series' China research is about the long-wheelbase G68 (as on the rings). */
export const researchCars = (it: ResearchItem) => it.cars.map((c) => (c === "G60" && it.region === "CN" ? "G68" : c));

export function passResearch(f: Filter | null, it: ResearchItem) {
  if (!f) return true;
  if (f.dim === "car") return researchCars(it).some((c) => f.values.has(c));
  if (f.dim === "market") return it.market == null || f.values.has(it.market);
  if (f.dim === "tier") return f.values.has(key(it.tier));
  return true;
}
export function passStudy(f: Filter | null, s: StudyItem) {
  if (!f) return true;
  if (f.dim === "car") return f.values.has(s.car);
  if (f.dim === "market") return f.values.has(s.market);
  return true;
}
export function passOption(f: Filter | null, o: OptionItem) {
  if (!f) return true;
  if (f.dim === "car") return f.values.has(o.car);
  if (f.dim === "category") return f.values.has(key(o.category));
  return true;
}
export function passSales(f: Filter | null, r: SalesRow) {
  if (!f) return true;
  if (f.dim === "car") return f.values.has(r.car);
  if (f.dim === "market") return f.values.has(r.market);
  return true;
}

/** 1 = the comment passes. Filters that don't apply to comments pass them all. */
export function commentMask(points: PointsPayload, f: Filter | null) {
  const m = new Uint8Array(points.n).fill(1);
  if (!f || !isCommentDim(f.dim)) return m;
  const col = points.cols[f.dim], dict = points.dict[f.dim] as (string | null)[];
  for (let i = 0; i < points.n; i++) m[i] = col[i] >= 0 && f.values.has(key(dict[col[i]])) ? 1 : 0;
  return m;
}

const TIER_NAME: Record<string, string> = { T1: "T1 · official", T2: "T2 · press & analysts", T3: "T3 · forums & social" };

/** The values a dimension offers, with how many items visible at this checkpoint carry each one. */
export function keyValues(dim: Dim, points: PointsPayload, src: SourcesPayload | undefined, position: number) {
  const n = new Map<string, number>();
  const add = (v: string | null | undefined) => n.set(key(v), (n.get(key(v)) ?? 0) + 1);
  if (isCommentDim(dim)) {
    const col = points.cols[dim], dict = points.dict[dim] as (string | null)[], cps = points.cols.cp;
    for (let i = 0; i < points.n; i++) if (col[i] >= 0 && cps[i] <= position) add(dict[col[i]]);
  }
  const research = (src?.research ?? []).filter((r) => position > 1 || !r.new);
  if (dim === "car") {
    for (const r of research) new Set(researchCars(r)).forEach(add);
    for (const s of src?.study ?? []) add(s.car);
    for (const o of src?.options ?? []) add(o.car);
    for (const r of src?.sales ?? []) add(r.car);
  }
  if (dim === "market") {
    for (const r of research) if (r.market) add(r.market);
    for (const s of src?.study ?? []) add(s.market);
    for (const r of src?.sales ?? []) add(r.market);
  }
  if (dim === "tier") for (const r of research) add(r.tier);
  if (dim === "category") for (const o of src?.options ?? []) add(o.category);

  const order: string[] =
    dim === "car" ? [...CARS] : dim === "market" ? ["EU", "US", "CN", "RoW"] : dim === "tier" ? ["T1", "T2", "T3"]
      : isCommentDim(dim) ? (points.dict[dim] as (string | null)[]).map(key)
        : [...n.keys()].sort((a, b) => (n.get(b) ?? 0) - (n.get(a) ?? 0));
  return order.filter((v) => n.get(v)).map((v) => ({ v, name: valueName(dim, v), n: n.get(v)! }));
}

function valueName(dim: Dim, v: string) {
  if (v === NONE) return dim === "type" ? "Unlabelled" : "Unknown";
  if (dim === "car") return CAR_NAME[v] ?? v;
  if (dim === "market") return MARKET_NAME[v] ?? v;
  if (dim === "tier") return TIER_NAME[v] ?? v;
  return v;
}

