// Bottom-right checkpoint dial. It reuses the scene's date ring: one arc from JUL 25 to JUL 26 with a tick per month,
// each checkpoint a node at its cut-off date. The filled arc is what is known at the active checkpoint; the blue hand
// stands on its cut-off and sweeps there with the same timing as the 3D sweep. Beside it: the checkpoints as tabs (the
// accessible control; the dial's nodes are a mouse shortcut) and what the sweep did to the earlier checkpoint's tracks.
import { useCheckpoint, CHECKPOINT_ORDER } from "@/state/checkpoint";
import type { Checkpoint, CheckpointId } from "@/lib/types";
import "./sweep.css";

const fmt = (n: number | undefined) => (n == null ? "–" : n.toLocaleString("en-US"));

const T0 = Date.parse("2025-07-01"), T1 = Date.parse("2026-07-31");   // the scene's date ring
const FALLBACK: Record<CheckpointId, string> = { cp1: "2026-01-31", cp2: "2026-07-31" };
const SIZE = 104, C = SIZE / 2, R = 40, START = -135, SPAN = 270;      // degrees from 12 o'clock, clockwise; gap at the bottom

const angleOf = (iso: string) => START + SPAN * Math.min(1, Math.max(0, (Date.parse(iso) - T0) / (T1 - T0)));
const pt = (deg: number, r = R): [number, number] => {
  const a = (deg * Math.PI) / 180;
  return [C + r * Math.sin(a), C - r * Math.cos(a)];
};
const arc = (a0: number, a1: number, r = R) => {
  const [x0, y0] = pt(a0, r), [x1, y1] = pt(a1, r);
  return `M ${x0} ${y0} A ${r} ${r} 0 ${a1 - a0 > 180 ? 1 : 0} 1 ${x1} ${y1}`;
};
const MONTHS = Array.from({ length: 13 }, (_, i) => {
  const d = new Date(Date.UTC(2025, 6 + i, 1));
  return { a: angleOf(d.toISOString().slice(0, 10)), major: d.getUTCMonth() === 0 || d.getUTCMonth() === 6 };
});

export function SweepControl() {
  const { cp, setCp, checkpoints } = useCheckpoint();
  const byId = Object.fromEntries((checkpoints ?? []).map((c) => [c.id, c])) as Partial<Record<CheckpointId, Checkpoint>>;
  // Same groups as the readout (comments, research, BMW data), so held + new = everything visible now.
  const sum = (c: Checkpoint | undefined, f: "visible" | "new") =>
    c ? (["feedback", "research", "study", "option_list", "sales"] as const).reduce((n, k) => n + c.sources[k][f], 0) : undefined;
  const cur = byId[cp], parent = cur?.parent_id ? byId[cur.parent_id] : undefined;
  const cutoff = (id: CheckpointId) => byId[id]?.cutoff ?? FALLBACK[id];
  const label = (id: CheckpointId) => byId[id]?.label ?? (id === "cp1" ? "JAN 26" : "JUL 26");
  const hand = angleOf(cutoff(cp));
  const known = (hand - START) / SPAN;
  const at = CHECKPOINT_ORDER.indexOf(cp);

  return (
    <div className="sweepctl">
      <svg className="sweepctl-dial" viewBox={`0 0 ${SIZE} ${SIZE}`} aria-hidden>
        {MONTHS.map((m, i) => {
          const [x0, y0] = pt(m.a, R + 4), [x1, y1] = pt(m.a, R + (m.major ? 9 : 6));
          return <line key={i} className="sweepctl-tick" data-major={m.major ? "" : undefined} x1={x0} y1={y0} x2={x1} y2={y1} />;
        })}
        <path className="sweepctl-track" d={arc(START, START + SPAN)} />
        <path className="sweepctl-known" d={arc(START, START + SPAN)} pathLength={1} style={{ strokeDasharray: `${known} 1` }} />
        <g className="sweepctl-hand" style={{ transform: `rotate(${hand}deg)`, transformOrigin: `${C}px ${C}px` }}>
          <path d={`M ${C} ${C} L ${pt(-28)[0]} ${pt(-28)[1]} A ${R} ${R} 0 0 1 ${C} ${C - R} Z`} />
          <line x1={C} y1={C} x2={C} y2={C - R} />
        </g>
        <circle className="sweepctl-hub" cx={C} cy={C} r={1.75} />
        {CHECKPOINT_ORDER.map((id, i) => {
          const [x, y] = pt(angleOf(cutoff(id)));
          return (
            <g key={id} className="sweepctl-node" data-state={id === cp ? "active" : i < at ? "built" : "idle"} onClick={() => setCp(id)}>
              <circle className="sweepctl-halo" cx={x} cy={y} r={8} />
              <circle className="sweepctl-dot" cx={x} cy={y} r={4.5} />
              <circle className="sweepctl-hit" cx={x} cy={y} r={13} />
            </g>
          );
        })}
      </svg>

      <div className="sweepctl-side">
        <div className="sweepctl-head"><span className="label">Checkpoint</span><span className="label sweepctl-keys">← →</span></div>
        <div className="sweepctl-tabs" role="radiogroup" aria-label="Checkpoint">
          {CHECKPOINT_ORDER.map((id) => (
            <button key={id} role="radio" aria-checked={cp === id} onClick={() => setCp(id)}>{label(id)}</button>
          ))}
        </div>
        <dl className="sweepctl-counts" aria-live="polite">
          {parent ? (
            <>
              <div><dt className="sr-only">Held from {label(parent.id)}</dt><i className="mark held" aria-hidden /><dd className="num">{fmt(sum(parent, "visible"))}</dd><span className="label" aria-hidden>held</span></div>
              <div><dt className="sr-only">New in {label(cp)}</dt><i className="mark new" aria-hidden /><dd className="num">{fmt(sum(cur, "new"))}</dd><span className="label" aria-hidden>new</span></div>
            </>
          ) : (
            <div><dt className="sr-only">Acquired</dt><i className="mark new" aria-hidden /><dd className="num">{fmt(sum(cur, "visible"))}</dd><span className="label" aria-hidden>acquired</span></div>
          )}
        </dl>
      </div>
    </div>
  );
}

